/*
 * A357474  Squarely correct numbers.
 * https://oeis.org/A357474
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   digit_len, ensure_capacity, floor_sqrt, get_digits
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A357474 – Squarely correct numbers
 * Generated by linear enumeration and a DP test that scans the
 * decimal digits (MSD first) to split the number into blocks that
 * are positive perfect squares without leading zeros. */
 
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Utility headers provided by the build */
#include "../utils/floor_sqrt.h"   /* floor_sqrt(seq_t) */
#include "../utils/get_digits.h"   /* get_digits(seq_t, uint8_t*, size_t*) */
#include "../utils/digit_len.h"    /* digit_len(seq_t) */
#include "../utils/ensure_capacity.h"  /* ensure_capacity(size_t, size_t*, void**, size_t)  */

/* Test whether a positive seq_t is a perfect square without leading zeros. */
static bool is_square_seq(seq_t n)
{
    if (n == 0)
        return false;
    seq_t r = floor_sqrt(n);
    return r * r == n;
}

/* Determine whether the decimal representation of x can be split
 * into blocks, each of which is a positive perfect square.  */
static bool qualifies(seq_t x)
{
    if (x == 0)
        return false;

    /* Determine the number of decimal digits */
    uint64_t dlen = (uint64_t)digit_len(x);

    /* Use a small static buffer for typical lengths */
    uint8_t  stack_buf[200];
    bool     stack_dp[201];              /* +1 for dp[0] */
    uint8_t *digits = stack_buf;
    bool    *dp     = stack_dp;
    bool     use_stack = dlen <= 200;

    if (!use_stack) {
        digits = (uint8_t*)malloc(dlen);
        dp     = (bool*)malloc((dlen + 1) * sizeof(*dp));
    }

    /* Fill the digits array in little‑endian order (LSD first) */
    size_t len;
    get_digits(x, digits, &len);
    if (len != dlen)  /* just in case get_digits reported fewer digits */
        len = dlen;

    /* Reverse digits to obtain most‑significant first */
    for (size_t l = 0, r = len - 1; l < r; ++l, --r) {
        uint8_t tmp = digits[l];
        digits[l] = digits[r];
        digits[r] = tmp;
    }

    /* Dynamic programming over split positions */
    memset(dp, 0, (len + 1) * sizeof(*dp));
    dp[0] = true;

    for (size_t i = 0; i < len; ++i) {
        if (!dp[i])
            continue;
        if (digits[i] == 0)    /* cannot start a block with a leading zero */
            continue;

        seq_t block = 0;
        for (size_t j = i; j < len; ++j) {
            block = block * 10 + digits[j];
            if (is_square_seq(block))
                dp[j + 1] = true;
        }
    }

    bool ok = dp[len];

    /* Clean up when dynamic memory was used */
    if (!use_stack) {
        free(digits);
        free(dp);
    }

    return ok;
}

/* Cached storage for the sequence.  Threads or re‑entrancy are not
 * required by the current problem constraints.                     */
static idx_t  s_last_checked = 0;   /* last integer that was tested       */
static seq_t *s_cache        = NULL;/* array of found terms                */
static size_t s_cache_cap    = 0;   /* capacity of the cache array         */
static size_t s_cache_size   = 0;   /* number of terms stored in s_cache   */

/* Return the nth term (n ≥ 1) of the sequence.                       */
seq_t a(idx_t n)
{
    if (n == 0)            /* undefined for offset 1 – harmless fallback */
        return 0;

    /* Extend the cache until we have at least n terms */
    while (s_cache_size < (size_t)n) {
        seq_t candidate = ++s_last_checked;
        if (qualifies(candidate)) {
            ensure_capacity(s_cache_size + 1, &s_cache_cap,
                            (void**)&s_cache, sizeof(seq_t));
            s_cache[s_cache_size++] = candidate;
        }
    }
    return s_cache[n - 1];
}
